ALTER TABLE tenants ADD COLUMN business_email varchar(254), ADD COLUMN business_phone varchar(32), ADD COLUMN business_address varchar(1000), ADD COLUMN country varchar(80) NOT NULL DEFAULT 'India', ADD COLUMN timezone varchar(80) NOT NULL DEFAULT 'Asia/Kolkata', ADD COLUMN currency varchar(3) NOT NULL DEFAULT 'INR', ADD COLUMN status varchar(24) NOT NULL DEFAULT 'ACTIVE', ADD COLUMN subscription_plan varchar(40) NOT NULL DEFAULT 'FOUNDATION', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN version bigint NOT NULL DEFAULT 0;
ALTER TABLE tenants ADD CONSTRAINT tenant_status_check CHECK(status IN ('ACTIVE','SUSPENDED','INACTIVE'));
ALTER TABLE branches ADD COLUMN branch_code varchar(20), ADD COLUMN address varchar(1000), ADD COLUMN state varchar(100), ADD COLUMN postal_code varchar(20), ADD COLUMN phone varchar(32), ADD COLUMN email varchar(254), ADD COLUMN timezone varchar(80) NOT NULL DEFAULT 'Asia/Kolkata', ADD COLUMN operating_hours jsonb NOT NULL DEFAULT '{}', ADD COLUMN settings jsonb NOT NULL DEFAULT '{}', ADD COLUMN status varchar(24) NOT NULL DEFAULT 'ACTIVE', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN version bigint NOT NULL DEFAULT 0;
UPDATE branches SET branch_code='BR-'||upper(substr(replace(id::text,'-',''),1,12));
ALTER TABLE branches ALTER COLUMN branch_code SET NOT NULL;
ALTER TABLE branches ADD CONSTRAINT branch_tenant_identity UNIQUE(tenant_id,id), ADD CONSTRAINT branch_code_unique UNIQUE(tenant_id,branch_code), ADD CONSTRAINT branch_status_check CHECK(status IN ('ACTIVE','INACTIVE')), ADD CONSTRAINT branch_code_upper CHECK(branch_code=upper(branch_code));
CREATE TABLE platform_users(id uuid PRIMARY KEY,issuer varchar(512) NOT NULL,subject varchar(255) NOT NULL,email varchar(254) NOT NULL,email_verified boolean NOT NULL,display_name varchar(120) NOT NULL,phone varchar(32),status varchar(32) NOT NULL DEFAULT 'ACTIVE',platform_admin boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issuer,subject));
CREATE TABLE roles(code varchar(40) PRIMARY KEY);
CREATE TABLE permissions(code varchar(80) PRIMARY KEY);
CREATE TABLE role_permissions(role varchar(40) NOT NULL REFERENCES roles(code),permission varchar(80) NOT NULL REFERENCES permissions(code),PRIMARY KEY(role,permission));
CREATE TABLE tenant_memberships(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES platform_users(id),role varchar(40) NOT NULL REFERENCES roles(code),scope varchar(16) NOT NULL CHECK(scope IN ('TENANT','BRANCHES','NONE')),status varchar(32) NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','MIGRATION_REQUIRED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,user_id),UNIQUE(tenant_id,id),CHECK(role!='PLATFORM_ADMIN'),CHECK((role='BRAND_OWNER' AND scope='TENANT') OR (role='CUSTOMER' AND scope='NONE') OR (role NOT IN ('BRAND_OWNER','CUSTOMER') AND scope='BRANCHES')));
CREATE INDEX membership_user_status ON tenant_memberships(user_id,status);
CREATE TABLE branch_memberships(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,branch_id uuid NOT NULL,PRIMARY KEY(membership_id,branch_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE staff_invitations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),email varchar(254) NOT NULL,role varchar(40) NOT NULL REFERENCES roles(code),token_hash varchar(64) NOT NULL UNIQUE,status varchar(24) NOT NULL CHECK(status IN ('PENDING','ACCEPTED','REVOKED')),inviter_id uuid NOT NULL REFERENCES platform_users(id),expires_at timestamptz NOT NULL,accepted_by uuid REFERENCES platform_users(id),accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX invitation_pending_email ON staff_invitations(tenant_id,email) WHERE status='PENDING';
CREATE INDEX invitation_tenant_created ON staff_invitations(tenant_id,created_at);
CREATE TABLE invitation_branches(tenant_id uuid NOT NULL,invitation_id uuid NOT NULL,branch_id uuid NOT NULL,PRIMARY KEY(invitation_id,branch_id),FOREIGN KEY(tenant_id,invitation_id) REFERENCES staff_invitations(tenant_id,id),FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE invitation_mail_outbox(id uuid PRIMARY KEY,invitation_id uuid NOT NULL REFERENCES staff_invitations(id),recipient varchar(254) NOT NULL,encrypted_body text NOT NULL,status varchar(24) NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX mail_outbox_due ON invitation_mail_outbox(status,next_attempt_at);
CREATE TABLE audit_events(id uuid PRIMARY KEY,actor_id uuid,tenant_id uuid,branch_id uuid,action varchar(80) NOT NULL,target_id varchar(255),outcome varchar(24) NOT NULL,correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_tenant_created ON audit_events(tenant_id,created_at);
